import type { NextRequest } from 'next/server'

// In Next.js 16 the `middleware.ts` convention was renamed to `proxy.ts`.
// This runs on the server before every request completes.
export function proxy(request: NextRequest) {
  // Log the incoming request pathname.
  console.log(`[proxy] ${request.nextUrl.pathname}`)

  // Generate a unique id for this request and attach it to the response.
  const requestId = crypto.randomUUID()

  const response = NextResponse.next({
    request: {
      headers: request.headers,
    },
  })

  response.headers.set('X-Request-Id', requestId)

  return response
}

// No `matcher` => this proxy runs on every request, so the header is added to
// all responses.
export const config = {
  matcher: [
    // Match every path except Next.js internals and static assets, so the
    // header still applies to all app routes without interfering with
    // static file serving.
    '/((?!_next/static|_next/image|favicon.ico).*)',
  ],
}
"}

